static bool bilipai_with_decoder_owner(struct mp_stream_info *info,
    void (*use)(void *, struct mp_decoder_wrapper *), void *ctx)
{
    struct chain *p = info->priv;
    if (!use || !p->bilipai_decoder_observer)
        return false;
    struct mp_bilipai_active_decoder active = {0};
    // Reject groups/unknown/retired decoders using the real existing control.
    // This query returns after dispatch exclusion; use() is OUTSIDE that lock.
    if (mp_decoder_wrapper_control(p->bilipai_decoder_observer,
            VDCTRL_BILIPAI_GET_ACTIVE_DECODER, &active) != CONTROL_TRUE ||
        !active.instance_id || !active.epoch_id)
        return false;
    use(ctx, p->bilipai_decoder_observer);
    return true; // lifetime borrow only, never a later epoch/GPU/HDR proof
}

