{
    MPContext *mpctx = ctx;
    if (action == M_PROPERTY_GET_TYPE) {
        *(struct m_option *)arg = (struct m_option){.type = CONF_TYPE_NODE};
        return M_PROPERTY_OK;
    }
    if (action != M_PROPERTY_GET) return M_PROPERTY_NOT_IMPLEMENTED;
    struct mp_bilipai_presentation p = {0};
    if (!mpctx->video_out ||
        vo_control(mpctx->video_out, VOCTRL_BILIPAI_RTX_SNAPSHOT, &p) <= 0 ||
        p.version != 1 || !p.serial || p.serial > INT64_MAX || p.epoch > INT64_MAX)
        return M_PROPERTY_UNAVAILABLE;
    struct mpv_node node;
    node_init(&node, MPV_FORMAT_NODE_MAP, NULL);
    node_map_add(&node, "schema", MPV_FORMAT_INT64)->u.int64 = 1;
    node_map_add(&node, "serial", MPV_FORMAT_INT64)->u.int64 = p.serial;
    node_map_add(&node, "epoch", MPV_FORMAT_INT64)->u.int64 = p.epoch;
    node_map_add(&node, "reason", MPV_FORMAT_INT64)->u.int64 = p.reason;
    node_map_add(&node, "present-hresult", MPV_FORMAT_INT64)->u.int64 = p.present_hresult;
    node_map_add(&node, "statistics-hresult", MPV_FORMAT_INT64)->u.int64 = p.statistics_hresult;
    bilipai_receipt_node(node_map_add(&node, "queued", MPV_FORMAT_NODE_MAP), &p.queued);
    bilipai_receipt_node(node_map_add(&node, "displayed", MPV_FORMAT_NODE_MAP), &p.displayed);
    *(struct mpv_node *)arg = node;
    return M_PROPERTY_OK;
}

