const struct mp_bilipai_d3d11_ready *
mp_image_bilipai_d3d11_ready(const struct mp_image *image)
{
    if (!image || !image->bilipai_d3d11_ready ||
        !image->bilipai_d3d11_ready->data ||
        image->bilipai_d3d11_ready->size != sizeof(struct mp_bilipai_d3d11_ready) ||
        image->params.bilipai_decoder_current_reference != 1 ||
        image->imgfmt != IMGFMT_D3D11 || image->params.imgfmt != IMGFMT_D3D11 ||
        image->params.hw_subfmt != pixfmt2imgfmt(AV_PIX_FMT_P010LE)) return NULL;
    const struct mp_bilipai_d3d11_ready *r = (const void *)image->bilipai_d3d11_ready->data;
    if (r->version != MP_BILIPAI_D3D11_READY_VERSION || r->reserved ||
        !r->signal_value || r->signal_value == UINT64_MAX ||
        !r->fence || !r->device || !r->device_context || !r->texture ||
        image->w != r->width || image->h != r->height ||
        image->params.w != r->width || image->params.h != r->height ||
        image->planes[0] != r->texture ||
        (uintptr_t)image->planes[1] != r->array_slice ||
        !image->bufs[0] || !r->source_bufs[0] ||
        !bilipai_ready_same_buffer(image->hwctx, r->source_hwctx) ||
        !mp_image_bilipai_decoder_origin_equal(&image->params.bilipai_decoder_origin,
                                               &r->origin)) return NULL;
    for (int n = 0; n < MP_MAX_PLANES; ++n) {
        if (image->planes[n] != r->planes[n] || image->stride[n] != r->stride[n] ||
            !bilipai_ready_same_buffer(image->bufs[n], r->source_bufs[n])) return NULL;
    }
    // Existing mutation hooks clear decoder_current_reference, not this ref.
    // Keeping an unusable receipt until ordinary image destruction is bounded
    // by the existing frame refs and avoids unref of shallow stack views.
    return r;
}

