static void bilipai_update_statistics(struct ra_swapchain *sw)
{
    struct priv *p = sw->priv;
    if (p->bilipai_counter_failed || !p->bilipai_feedback.queued.valid)
        return;
    if (!bilipai_statistics_environment(sw)) {
        p->bilipai_feedback.displayed.valid = false;
        p->bilipai_feedback.reason = MP_BILIPAI_PROOF_UNSUPPORTED;
        return;
    }
    DXGI_FRAME_STATISTICS stats = {0};
    HRESULT hr = IDXGISwapChain_GetFrameStatistics(p->swapchain, &stats);
    p->bilipai_feedback.statistics_hresult = hr;
    if (hr == DXGI_ERROR_FRAME_STATISTICS_DISJOINT) {
        struct mp_bilipai_present_receipt queued = p->bilipai_feedback.queued;
        bilipai_invalidate(p, MP_BILIPAI_PROOF_DISJOINT, true);
        // Preserve only truthful queue acceptance; previous display sequence is gone.
        queued.epoch = p->bilipai_feedback.epoch;
        p->bilipai_feedback.queued = queued;
        return;
    }
    if (hr != S_OK || !stats.PresentCount || !stats.PresentRefreshCount ||
        !stats.SyncRefreshCount || stats.SyncQPCTime.QuadPart <= 0) {
        p->bilipai_feedback.displayed.valid = false;
        return;
    }
    for (unsigned n = 0; n < VO_MAX_SWAPCHAIN_DEPTH; ++n) {
        const struct mp_bilipai_present_receipt *entry = &p->bilipai_ring[n];
        if (!entry->valid || entry->epoch != p->bilipai_feedback.epoch ||
            entry->present_count != stats.PresentCount ||
            !bilipai_same_generation(&entry->render.token,
                                     &p->bilipai_feedback.queued.render.token))
            continue;
        if (p->bilipai_feedback.displayed.valid &&
            p->bilipai_feedback.displayed.present_count == entry->present_count &&
            mp_bilipai_token_equal(&p->bilipai_feedback.displayed.render.token,
                                  &entry->render.token))
            return;
        p->bilipai_feedback.displayed = *entry;
        p->bilipai_feedback.displayed.refresh_count = stats.PresentRefreshCount;
        p->bilipai_feedback.displayed.sync_qpc = stats.SyncQPCTime.QuadPart;
        p->bilipai_feedback.reason = MP_BILIPAI_PROOF_DISPLAY_MATCH;
        bilipai_step(p);
        return;
    }
    // Unknown/dropped/overwritten IDs cannot inherit another frame's evidence.
    p->bilipai_feedback.displayed.valid = false;
}
