static uint32_t bilipai_packet_refusals(const AVPacketSideData *side, int count)
{
    if (count < 0 || count > 128 || (count && !side))
        return MP_BILIPAI_HDR_DECODER_METADATA_UNKNOWN;
    uint32_t flags = 0;
    for (int n = 0; n < count; n++) {
        switch (side[n].type) {
        case AV_PKT_DATA_DOVI_CONF: flags |= MP_BILIPAI_HDR_DOVI_CONFIG_PRESENT; break;
        case AV_PKT_DATA_ICC_PROFILE: flags |= MP_BILIPAI_HDR_ICC_PRESENT; break;
        case AV_PKT_DATA_DYNAMIC_HDR10_PLUS: flags |= MP_BILIPAI_HDR_PLUS_PRESENT; break;
        case AV_PKT_DATA_DYNAMIC_HDR_SMPTE_2094_APP5: flags |= MP_BILIPAI_HDR_APP5_PRESENT; break;
        default: break;
        }
        // Presence survives even when payload contents cannot be trusted.
        if (side[n].size && !side[n].data)
            flags |= MP_BILIPAI_HDR_DECODER_METADATA_UNKNOWN;
    }
    return flags;
}

static uint32_t bilipai_decoded_refusals(AVFrameSideData *const *side, int count)
{
    if (count < 0 || count > 128 || (count && !side))
        return MP_BILIPAI_HDR_DECODER_METADATA_UNKNOWN;
    uint32_t flags = 0;
    for (int n = 0; n < count; n++) {
        if (!side[n]) { flags |= MP_BILIPAI_HDR_DECODER_METADATA_UNKNOWN; continue; }
        switch (side[n]->type) {
        case AV_FRAME_DATA_DYNAMIC_HDR_PLUS: flags |= MP_BILIPAI_HDR_PLUS_PRESENT; break;
        case AV_FRAME_DATA_DYNAMIC_HDR_VIVID: flags |= MP_BILIPAI_HDR_VIVID_PRESENT; break;
        case AV_FRAME_DATA_DYNAMIC_HDR_SMPTE_2094_APP5: flags |= MP_BILIPAI_HDR_APP5_PRESENT; break;
        case AV_FRAME_DATA_DOVI_METADATA: flags |= MP_BILIPAI_HDR_DOVI_METADATA_PRESENT; break;
        case AV_FRAME_DATA_DOVI_RPU_BUFFER: flags |= MP_BILIPAI_HDR_DOVI_RPU_PRESENT; break;
        case AV_FRAME_DATA_ICC_PROFILE: flags |= MP_BILIPAI_HDR_ICC_PRESENT; break;
        default: break;
        }
        if (side[n]->size && !side[n]->data)
