 * status retains that slot permanently. Two unknown generations fall back to
 * ordinary playback; no CPU wait or unbounded owner registry is introduced. */
struct bilipai_ready_custody {
    AVBufferRef *lease, *device_ref, *consumer_ref;
    IUnknown *device_identity, *context_identity;
    ID3D11Device *device;
    ID3D11DeviceContext *context;
    ID3D11DeviceContext4 *context4;
    ID3D11Fence *fence;
