static _Thread_local bool bilipai_ready_scope_gpu_permitted;

static bool bilipai_ready_ref_equal(const AVBufferRef *a, const AVBufferRef *b)
{
    return a && b && a->buffer == b->buffer && a->data == b->data && a->size == b->size;
}

static struct bilipai_ready_custody *
bilipai_ready_from_ref_locked(const struct mp_bilipai_d3d11_ready *r)
{
    if (!r || r->version != MP_BILIPAI_D3D11_READY_VERSION || r->reserved ||
        !r->custody_ref || r->custody_ref->size != sizeof(struct bilipai_ready_custody))
        return NULL;
    for (int n = 0; n < 2; ++n) {
        if (!bilipai_ready_ref_equal(r->custody_ref, bilipai_ready_slots[n])) continue;
        struct bilipai_ready_custody *s = (void *)bilipai_ready_slots[n]->data;
        if (r->generation_id != s->generation_id || r->fence != s->fence ||
            r->device != s->device || r->device_context != s->context ||
            !r->signal_value || r->signal_value > s->value || !s->producer_known)
            return NULL;
        return s;
    }
    return NULL;
}

static void bilipai_ready_custody_free(void *opaque, uint8_t *data)
{
    (void)opaque;
    struct bilipai_ready_custody *s = (void *)data;
    /* Only the pool's proven-retirement path drops its last owning ref, outside
     * both locks. No consumer/receipt/reset path can free live COM custody. */
    if (s->fence) ID3D11Fence_Release(s->fence);
    if (s->context4) ID3D11DeviceContext4_Release(s->context4);
    if (s->context_identity) IUnknown_Release(s->context_identity);
    if (s->device_identity) IUnknown_Release(s->device_identity);
    av_buffer_unref(&s->device_ref);
    av_free(s);
}

static void bilipai_ready_collect(const AVBufferRef *requested_owner)
{
    if (!d3d11_bilipai_default_owner_known(requested_owner) ||
        atomic_flag_test_and_set(&bilipai_ready_slot_busy)) return;
    AVBufferRef *retired[2] = {0};
    for (int n = 0; n < 2; ++n) {
        if (!bilipai_ready_slots[n]) continue;
        struct bilipai_ready_custody *s = (void *)bilipai_ready_slots[n]->data;
        // Called by a real decoded frame before acquiring its original mutex.
        // Only a different known constructor owner revokes current issuance.
        if (!bilipai_ready_ref_equal(s->device_ref, requested_owner)) s->issuing = false;
        if (s->issuing || s->poisoned || s->consumer_ref ||
            av_buffer_get_ref_count(bilipai_ready_slots[n]) != 1) continue;
        if (!d3d11_bilipai_default_owner_known(s->device_ref) ||
            ID3D11Device_GetDeviceRemovedReason(s->device) != S_OK) {
            s->poisoned = true; continue;
        }
        if (s->attempted) {
            uint64_t completed = ID3D11Fence_GetCompletedValue(s->fence);
            if (completed == UINT64_MAX) { s->poisoned = true; continue; }
            if (!s->producer_known || !s->value || completed < s->value) continue;
        }
        retired[n] = bilipai_ready_slots[n]; bilipai_ready_slots[n] = NULL;
    }
    atomic_flag_clear(&bilipai_ready_slot_busy);
    // No decoder/context/custody lock is held; callbacks may release actual HWctx.
    for (int n = 0; n < 2; ++n) av_buffer_unref(&retired[n]);
}

static void bilipai_ready_free(void *opaque, uint8_t *data)
{
    (void)opaque;
    struct mp_bilipai_d3d11_ready *r = (void *)data;
    for (int n = 0; n < MP_MAX_PLANES; ++n) av_buffer_unref(&r->source_bufs[n]);
    av_buffer_unref(&r->source_hwctx);
    av_buffer_unref(&r->custody_ref);
    // A live/unknown generation still has its pool owner; no COM Release here.
    av_free(r);
}

static struct bilipai_ready_custody *
bilipai_ready_owner(const AVBufferRef *device_ref, AVD3D11VADeviceContext *d)
{
    IUnknown *device_id = NULL, *context_id = NULL, *video_id = NULL;
    ID3D11Device5 *device5 = NULL;
    ID3D11DeviceContext4 *context4 = NULL;
    ID3D11Fence *fence = NULL;
    AVBufferRef *held = NULL, *lease = NULL;
    ID3D11Device *context_device = NULL;
    IUnknown *context_device_id = NULL;
    struct bilipai_ready_custody *s = NULL, *created = NULL;
    int empty = -1;
    ID3D11DeviceContext_GetDevice(d->device_context, &context_device);
    if (!context_device ||
        IUnknown_QueryInterface((IUnknown *)context_device, &IID_IUnknown,
                                (void **)&context_device_id) != S_OK) goto done;
    if (ID3D11DeviceContext_GetType(d->device_context) != D3D11_DEVICE_CONTEXT_IMMEDIATE ||
        IUnknown_QueryInterface((IUnknown *)d->device, &IID_IUnknown,
                                (void **)&device_id) != S_OK ||
        IUnknown_QueryInterface((IUnknown *)d->device_context, &IID_IUnknown,
                                (void **)&context_id) != S_OK ||
        IUnknown_QueryInterface((IUnknown *)d->video_context, &IID_IUnknown,
                                (void **)&video_id) != S_OK || context_id != video_id ||
        context_device_id != device_id) goto done;
    for (int n = 0; n < 2; ++n) {
        if (!bilipai_ready_slots[n]) { if (empty < 0) empty = n; continue; }
        struct bilipai_ready_custody *p = (void *)bilipai_ready_slots[n]->data;
        if (!bilipai_ready_ref_equal(p->device_ref, device_ref)) continue;
        if (p->issuing && !p->poisoned && p->device_identity == device_id &&
            p->context_identity == context_id && p->device == d->device &&
            p->context == d->device_context && p->lock == d->lock &&
            p->unlock == d->unlock && p->lock_ctx == d->lock_ctx) s = p;
        goto done; // Never make a second generation of a still-retained owner.
    }
