        IUnknown_QueryInterface((IUnknown *)d->device, &IID_ID3D11Device5,
                                (void **)&device5) != S_OK ||
        IUnknown_QueryInterface((IUnknown *)d->device_context, &IID_ID3D11DeviceContext4,
                                (void **)&context4) != S_OK ||
        ID3D11Device5_CreateFence(device5, 0, D3D11_FENCE_FLAG_NONE,
                                 &IID_ID3D11Fence, (void **)&fence) != S_OK ||
