    created->device_ref = held; held = NULL;
    created->device_identity = device_id; device_id = NULL;
    created->context_identity = context_id; context_id = NULL;
    created->device = d->device; created->context = d->device_context;
    created->context4 = context4; context4 = NULL; created->fence = fence; fence = NULL;
    created->lock = d->lock; created->unlock = d->unlock; created->lock_ctx = d->lock_ctx;
    created->issuing = true;
    bilipai_ready_slots[empty] = lease; lease = NULL;
