static void bilipai_ready_use_free(void *opaque, uint8_t *data)
{
    (void)opaque;
    struct bilipai_ready_use *u = (void *)data;
    if (u->final_fence) ID3D11Fence_Release(u->final_fence);
    av_buffer_unref(&u->receipt_ref);
    av_free(u);
}

static struct bilipai_ready_use *bilipai_ready_use(const AVBufferRef *ticket)
{
    if (!ticket || !ticket->data || ticket->size != sizeof(struct bilipai_ready_use)) return NULL;
    struct bilipai_ready_use *u = (void *)ticket->data;
    return u->owner_thread == GetCurrentThreadId() && u->receipt_ref ? u : NULL;
}

AVBufferRef *mp_bilipai_d3d11_use_prepare(const AVBufferRef *receipt)
{
    if (bilipai_ready_scope_custody || !receipt || !receipt->data ||
        receipt->size != sizeof(struct mp_bilipai_d3d11_ready)) return NULL;
    const struct mp_bilipai_d3d11_ready *r = (const void *)receipt->data;
    if (r->version != MP_BILIPAI_D3D11_READY_VERSION || r->reserved) return NULL;
    struct bilipai_ready_use *u = av_mallocz(sizeof(*u));
    if (!u) return NULL;
    u->owner_thread = GetCurrentThreadId(); u->receipt_ref = av_buffer_ref(receipt);
    AVBufferRef *ticket = u->receipt_ref ? av_buffer_create((uint8_t *)u, sizeof(*u),
        bilipai_ready_use_free, NULL, 0) : NULL;
    if (!ticket) { bilipai_ready_use_free(NULL, (uint8_t *)u); return NULL; }
    bool ok = false;
    if (!atomic_flag_test_and_set(&bilipai_ready_slot_busy)) {
        struct bilipai_ready_custody *s = bilipai_ready_from_ref_locked(r);
        if (s && s->issuing && !s->poisoned && !s->consumer_ref &&
            d3d11_bilipai_default_owner_known(s->device_ref)) {
            s->consumer_ref = av_buffer_ref(ticket); // all refs prepared outside GPU scope
            ok = s->consumer_ref != NULL;
        }
        atomic_flag_clear(&bilipai_ready_slot_busy);
    }
    if (!ok) av_buffer_unref(&ticket);
    return ticket;
}

bool mp_bilipai_d3d11_use_attempt_locked(const AVBufferRef *ticket, const void *ready)
{
    /* No alloc/ref/free/COM/GPU operations. Current CPU scope never enables this.
     * Future dedicated submit scope supplies its original mutex+custody gate.
     * This only reserves failed-work lifetime; it is NOT GPU-use authority. */
    if (!bilipai_ready_scope_gpu_permitted || !bilipai_ready_scope_custody) return false;
    struct bilipai_ready_use *u = bilipai_ready_use(ticket);
    struct bilipai_ready_custody *s = bilipai_ready_scope_custody;
    const struct mp_bilipai_d3d11_ready *r = ready;
    if (!u || u->attempted || !r || bilipai_ready_from_ref_locked(r) != s ||
        !s->issuing || s->poisoned || !bilipai_ready_ref_equal(ticket, s->consumer_ref) ||
        u->receipt_ref->data != (const uint8_t *)r) return false;
    u->attempted = true; // sticky BEFORE the first possibly queued command
    return true;
}

bool mp_bilipai_d3d11_use_seal(const AVBufferRef *ticket, void *unknown, uint64_t value)
{
    struct bilipai_ready_use *u = bilipai_ready_scope_custody ? NULL : bilipai_ready_use(ticket);
    if (!u || !u->attempted || u->sealed || !unknown || !value || value == UINT64_MAX)
        return false;
    const struct mp_bilipai_d3d11_ready *r = (const void *)u->receipt_ref->data;
    ID3D11Fence *fence = NULL;
    ID3D11Device *device = NULL;
    IUnknown *did = NULL, *gid = NULL, *fid = NULL, *producer_id = NULL;
    bool valid = false;
    if (IUnknown_QueryInterface((IUnknown *)unknown, &IID_ID3D11Fence,
                                (void **)&fence) != S_OK) goto done;
    ID3D11Fence_GetDevice(fence, &device);
    if (!device || IUnknown_QueryInterface((IUnknown *)device, &IID_IUnknown,(void **)&did) != S_OK ||
        IUnknown_QueryInterface((IUnknown *)r->device,&IID_IUnknown,(void **)&gid) != S_OK ||
        IUnknown_QueryInterface((IUnknown *)fence,&IID_IUnknown,(void **)&fid) != S_OK ||
        IUnknown_QueryInterface((IUnknown *)r->fence,&IID_IUnknown,(void **)&producer_id) != S_OK ||
        did != gid || fid == producer_id || ID3D11Device_GetDeviceRemovedReason(device) != S_OK ||
        ID3D11Fence_GetCompletedValue(fence) == UINT64_MAX) goto done;
    if (!atomic_flag_test_and_set(&bilipai_ready_slot_busy)) {
        struct bilipai_ready_custody *s = bilipai_ready_from_ref_locked(r);
        if (s && !s->poisoned && bilipai_ready_ref_equal(ticket, s->consumer_ref)) {
            u->final_fence = fence; fence = NULL; u->final_value = value;
            u->sealed = true; valid = true;
        }
        atomic_flag_clear(&bilipai_ready_slot_busy);
    }
done:
    if (producer_id) IUnknown_Release(producer_id);
    if (fid) IUnknown_Release(fid);
    if (gid) IUnknown_Release(gid);
    if (did) IUnknown_Release(did);
    if (device) ID3D11Device_Release(device);
    if (fence) ID3D11Fence_Release(fence);
    return valid;
}

bool mp_bilipai_d3d11_use_retire(AVBufferRef **ticket)
{
    if (bilipai_ready_scope_custody || !ticket || !*ticket) return false;
    struct bilipai_ready_use *u = bilipai_ready_use(*ticket);
    if (!u || atomic_flag_test_and_set(&bilipai_ready_slot_busy)) return false;
    const struct mp_bilipai_d3d11_ready *r = (const void *)u->receipt_ref->data;
    struct bilipai_ready_custody *s = bilipai_ready_from_ref_locked(r);
    AVBufferRef *pool_ticket = NULL;
    bool safe = s && bilipai_ready_ref_equal(*ticket, s->consumer_ref);
    if (safe && u->attempted) {
        safe = !s->poisoned && u->sealed && u->final_fence && u->final_value;
        if (safe) {
