#include <dxgi.h>
#include <stdatomic.h>
#include <libavutil/mem.h>

/* Private default-owner provenance, created only by this actual wrapper.
 * AVHWDeviceContext::free is the constructor identity; unknown external
 * user_opaque is never dereferenced. FFmpeg keeps its original lock callbacks
 * and closes its default HANDLE during device_uninit, before this free hook.
 * This optional CPU record does not create a GPU queue/fence or lifetime slot.
 */
struct bilipai_d3d11_default_owner {
    AVHWDeviceContext *context;
    ID3D11Device *device;
    ID3D11DeviceContext *device_context;
    ID3D11VideoContext *video_context;
    void (*lock)(void *), (*unlock)(void *);
    HANDLE mutex;
    atomic_bool poisoned;
};

static void bilipai_d3d11_owner_free(AVHWDeviceContext *ctx)
{
    av_free(ctx->user_opaque);
    ctx->user_opaque = NULL;
}

static struct bilipai_d3d11_default_owner *
bilipai_d3d11_owner(const AVBufferRef *ref)
{
    if (!ref || !ref->data || ref->size < sizeof(AVHWDeviceContext)) return NULL;
    AVHWDeviceContext *ctx = (void *)ref->data;
    if (ctx->type != AV_HWDEVICE_TYPE_D3D11VA || !ctx->hwctx ||
        ctx->free != bilipai_d3d11_owner_free || !ctx->user_opaque) return NULL;
    struct bilipai_d3d11_default_owner *r = ctx->user_opaque;
    AVD3D11VADeviceContext *d = ctx->hwctx;
    if (r->context != ctx || !r->mutex || r->mutex == INVALID_HANDLE_VALUE ||
        !r->device || !r->device_context || !r->video_context || !r->lock || !r->unlock ||
        d->device != r->device || d->device_context != r->device_context ||
        d->video_context != r->video_context || d->lock != r->lock ||
        d->unlock != r->unlock || d->lock_ctx != r->mutex) return NULL;
    return r;
}

bool d3d11_bilipai_default_owner_known(const AVBufferRef *ref)
{
    struct bilipai_d3d11_default_owner *r = bilipai_d3d11_owner(ref);
    return r && !atomic_load(&r->poisoned);
}

bool d3d11_bilipai_default_try_lock(const AVBufferRef *ref)
{
    struct bilipai_d3d11_default_owner *r = bilipai_d3d11_owner(ref);
    if (!r || atomic_load(&r->poisoned)) return false;
    DWORD result = WaitForSingleObjectEx(r->mutex, 0, FALSE);
    if (result == WAIT_OBJECT_0) {
        if (!atomic_load(&r->poisoned)) return true;
        ReleaseMutex(r->mutex);
        return false;
    }
    if (result != WAIT_TIMEOUT) atomic_store(&r->poisoned, true);
    // WAIT_ABANDONED grants ownership despite the failed validity contract.
    // Relinquish it, but never issue a Signal or reuse this poisoned owner.
    if (result == WAIT_ABANDONED) ReleaseMutex(r->mutex);
    return false;
}

bool d3d11_bilipai_default_unlock(const AVBufferRef *ref)
{
    struct bilipai_d3d11_default_owner *r = bilipai_d3d11_owner(ref);
    if (!r) return false;
    bool ok = ReleaseMutex(r->mutex) != 0;
    if (!ok) atomic_store(&r->poisoned, true);
    return ok;
}

